package edu.bjfu.eldercare;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.util.*;import java.math.BigDecimal;import java.math.RoundingMode;import java.time.*;import static edu.bjfu.eldercare.Store.id;
@Service public class CareService {
 private final Store db;private final Crypto crypto;private final Scope scope;private final WorkflowService workflows;
 public CareService(Store d,Crypto c,Scope scope,WorkflowService workflows){db=d;crypto=c;this.scope=scope;this.workflows=workflows;}
 private void actor(Auth.User u){db.update("SET @actor=?",u.id()+":"+u.name());}
 public void elderScope(Auth.User u,long elder){db.one("SELECT id FROM elder WHERE id=? FOR UPDATE",elder);scope.elder(u,elder);}
 private Map<String,Object> orderScope(Auth.User u,long order){var o=db.one("SELECT * FROM service_order WHERE id=? FOR UPDATE",order);elderScope(u,id(o,"elder_id"));if(u.role().equals("CAREGIVER")&&db.count("SELECT COUNT(*) FROM v_dispatch_context d JOIN caregiver c ON c.id=d.caregiver_id WHERE d.order_id=? AND c.account_id=? AND d.status IN('WAITING','ACCEPTED')",order,u.id())==0)throw new Forbidden();return o;}
 private void workerScope(Auth.User u,long worker){scope.worker(u,worker);}
 private static String s(Map<String,Object> m,String k){Object v=m.get(k);if(v==null||v.toString().isBlank())throw new Rule("缺少字段: "+k);return v.toString();}
 private static long n(Map<String,Object> m,String k){try{return Long.parseLong(s(m,k));}catch(NumberFormatException e){throw new Rule("编号无效: "+k);}}
 private static boolean b(Map<String,Object> m,String k){String value=s(m,k);if(!value.equals("true")&&!value.equals("false"))throw new Rule("布尔值无效: "+k);return Boolean.parseBoolean(value);}

 private static LocalDateTime parseTime(String text){try{return LocalDateTime.parse(text);}catch(java.time.format.DateTimeParseException e){throw new Rule("时间格式应为 yyyy-MM-ddTHH:mm");}}
 private static BigDecimal price(Map<String,Object> item){
  BigDecimal price=(BigDecimal)item.get("price");
  return "HOUR".equals(item.get("unit"))?price.multiply(BigDecimal.valueOf(id(item,"duration_minutes"))).divide(BigDecimal.valueOf(60),2,RoundingMode.HALF_UP):price;
 }
 private List<Map<String,Object>> recommend(Auth.User u,long order){
  var o=orderScope(u,order);
  if(!Set.of("PENDING","ASSIGNED","ACCEPTED").contains(o.get("status")))throw new Rule("当前订单无需派单");
  db.call("assert_order",o.get("elder_id"),o.get("item_id"),o.get("community_id"),o.get("starts_at"),o.get("ends_at"));
  // Suggestions are advisory; assign_order rechecks under locks before reserving capacity.
  return db.rows("""
   SELECT s.id shift_id,c.id caregiver_id,c.name,s.starts_at,s.ends_at,s.capacity-s.used_count available
   FROM shift s JOIN caregiver c ON c.id=s.caregiver_id JOIN account ac ON ac.id=c.account_id
   WHERE c.status='ACTIVE' AND ac.active=1 AND s.status='OPEN' AND s.starts_at<=? AND s.ends_at>=?
   AND (s.used_count<s.capacity OR EXISTS(SELECT 1 FROM dispatch d WHERE d.shift_id=s.id AND d.active_order=?))
   AND EXISTS(SELECT 1 FROM caregiver_area a WHERE a.caregiver_id=c.id AND a.community_id=?)
   AND EXISTS(SELECT 1 FROM training_record tr WHERE tr.caregiver_id=c.id AND tr.result='PASS')
   AND EXISTS(SELECT 1 FROM credential x WHERE x.caregiver_id=c.id AND x.item_id=? AND x.valid_from<=LEAST(NOW(),?) AND x.valid_until>=GREATEST(NOW(),?))
   AND NOT EXISTS(SELECT 1 FROM inspection i WHERE i.status IN('OPEN','REVIEW') AND (i.caregiver_id=c.id OR i.order_id IN(SELECT order_id FROM v_dispatch_context WHERE caregiver_id=c.id AND status IN('ACCEPTED','FINISHED'))))
   AND NOT EXISTS(SELECT 1 FROM v_dispatch_context d JOIN service_order z ON z.id=d.order_id WHERE d.caregiver_id=c.id AND d.status IN('WAITING','ACCEPTED') AND z.id<>? AND z.starts_at<? AND z.ends_at>?)
   ORDER BY available DESC,c.id,s.id
   """,o.get("starts_at"),o.get("ends_at"),order,o.get("community_id"),o.get("item_id"),o.get("starts_at"),o.get("ends_at"),order,o.get("ends_at"),o.get("starts_at"));
 }
 @Transactional public Object execute(Auth.User u,String action,Map<String,Object> m){actor(u);if(workflows.handles(action))return workflows.execute(u,action,m);long x;
 switch(action){
 case "elder.create": Auth.role(u,"ADMIN");return db.insert("INSERT INTO elder(name,identity_hash,identity_cipher,birth_date,address,community_id) VALUES(?,?,?,?,?,?)",s(m,"name"),crypto.hash(s(m,"identity").strip().toUpperCase(Locale.ROOT)),crypto.encrypt(s(m,"identity").strip().toUpperCase(Locale.ROOT)),s(m,"birthDate"),s(m,"address"),u.community());
 case "guardian.create":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);if(db.count("SELECT COUNT(*) FROM account WHERE id=? AND role='FAMILY' AND community_id=?",n(m,"accountId"),u.community())!=1)throw new Rule("家属账号范围错误");return db.insert("INSERT INTO guardian(elder_id,account_id,relation_name,phone_cipher) VALUES(?,?,?,?)",x,n(m,"accountId"),s(m,"relation"),crypto.encrypt(s(m,"phone")));
 case "credential.create":Auth.role(u,"MANAGER");x=n(m,"caregiverId");workerScope(u,x);return db.insert("INSERT INTO credential(caregiver_id,item_id,certificate_no,certificate_level,valid_from,valid_until) VALUES(?,?,?,?,?,?)",x,n(m,"itemId"),s(m,"certificateNo"),s(m,"level"),s(m,"validFrom"),s(m,"validUntil"));
 case "caregiver.status":Auth.role(u,"MANAGER");x=n(m,"caregiverId");workerScope(u,x);return db.update("UPDATE caregiver SET status=? WHERE id=?",s(m,"status"),x);
 case "device.create":Auth.role(u,"ADMIN");return db.insert("INSERT INTO device(serial_no,type_name,location_note) VALUES(?,?,?)",s(m,"serial"),s(m,"type"),s(m,"location"));
 case "elder.update":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);return db.update("UPDATE elder SET address=? WHERE id=?",s(m,"address"),x);
 case "elder.transfer":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);var origin=db.one("SELECT * FROM elder WHERE id=? FOR UPDATE",x);if(db.count("SELECT COUNT(*) FROM service_order WHERE elder_id=? AND status NOT IN('COMPLETED','CANCELLED')",x)>0)throw new Rule("请先处理未完成订单");db.update("UPDATE care_plan p JOIN assessment a ON a.id=p.assessment_id SET p.status='PAUSED' WHERE a.elder_id=? AND p.status='ACTIVE'",x);db.update("UPDATE elder SET community_id=?,address=? WHERE id=?",n(m,"communityId"),s(m,"address"),x);db.insert("INSERT INTO audit_log(table_name,row_id,operation,actor,old_status,new_status) VALUES('elder',?,'TRANSFER',?,?,?)",x,u.name(),origin.get("community_id").toString(),s(m,"communityId"));return "迁移完成，原计划暂停，历史订单保留";
 case "elder.deactivate":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);if(db.count("SELECT COUNT(*) FROM service_order WHERE elder_id=? AND status NOT IN('COMPLETED','CANCELLED')",x)>0)throw new Rule("请先处理未完成订单");db.update("UPDATE care_plan p JOIN assessment a ON a.id=p.assessment_id SET p.status='PAUSED' WHERE a.elder_id=? AND p.status='ACTIVE'",x);return db.update("UPDATE elder SET status='INACTIVE' WHERE id=?",x);
 case "assessment.create":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);return db.insert("INSERT INTO assessment(elder_id,scale_name,score,ability_level,assessor_id,assessed_at,valid_until) VALUES(?,?,?,?,?,NOW(),?)",x,s(m,"scale"),n(m,"score"),s(m,"level"),u.id(),s(m,"validUntil"));
 case "plan.create":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);workerScope(u,n(m,"caregiverId"));if(db.count("SELECT COUNT(*) FROM assessment WHERE id=? AND elder_id=?",n(m,"assessmentId"),x)!=1)throw new Rule("评估不属于此老人");long plan=db.insert("INSERT INTO care_plan(assessment_id,bundle_id,caregiver_id,starts_at,ends_at) VALUES(?,?,?,?,?)",n(m,"assessmentId"),n(m,"bundleId"),n(m,"caregiverId"),s(m,"startsAt"),s(m,"endsAt"));db.update("INSERT INTO plan_item(plan_id,item_id,weekly_frequency) SELECT ?,item_id,weekly_frequency FROM bundle_item WHERE bundle_id=?",plan,n(m,"bundleId"));return plan;
 case "order.create":Auth.role(u,"ADMIN","FAMILY");x=n(m,"elderId");elderScope(u,x);var e=db.one("SELECT * FROM elder WHERE id=?",x);var item=db.one("SELECT * FROM service_item WHERE id=?",n(m,"itemId"));var start=parseTime(s(m,"startsAt"));var end=start.plusMinutes(id(item,"duration_minutes"));if(start.isBefore(LocalDateTime.now()))throw new Rule("预约时间必须在未来");return db.insert("INSERT INTO service_order(elder_id,item_id,community_id,starts_at,ends_at,address,channel,amount,created_by,position_x,position_y) VALUES(?,?,?,?,?,?,?,?,?,?,?)",x,item.get("id"),e.get("community_id"),start,end,e.get("address"),u.role().equals("FAMILY")?"FAMILY":Inputs.choice(Map.of("channel",Inputs.optional(m,"channel","COMMUNITY")),"channel","PHONE","COMMUNITY"),price(item),u.id(),e.get("position_x"),e.get("position_y"));
 case "order.recommend":Auth.role(u,"ADMIN");return recommend(u,n(m,"orderId"));
 case "order.assign":Auth.role(u,"ADMIN");x=n(m,"orderId");orderScope(u,x);db.call("assign_order",x,n(m,"shiftId"),s(m,"reason"));return "派单成功";
 case "order.accept":Auth.role(u,"CAREGIVER");x=n(m,"orderId");var o=orderScope(u,x);if(!o.get("status").equals("ASSIGNED"))throw new Rule("订单不可接单");var d=db.one("SELECT * FROM v_dispatch_context WHERE order_id=? AND status='WAITING'",x);db.call("assert_worker_order",x,d.get("shift_id"));db.update("UPDATE dispatch SET status='ACCEPTED',accepted_at=NOW() WHERE id=?",d.get("id"));return db.update("UPDATE service_order SET status='ACCEPTED' WHERE id=?",x);
 case "order.checkin":Auth.role(u,"CAREGIVER");x=n(m,"orderId");o=orderScope(u,x);if(!o.get("status").equals("ACCEPTED"))throw new Rule("订单未接单");d=db.one("SELECT * FROM v_dispatch_context WHERE order_id=? AND status='ACCEPTED'",x);db.call("assert_worker_order",x,d.get("shift_id"));db.insert("INSERT INTO attendance(dispatch_id,check_in,location_note,fence_ok) VALUES(?,NOW(6),?,?)",d.get("id"),s(m,"location"),b(m,"fenceOk"));return db.update("UPDATE service_order SET status='SERVING' WHERE id=?",x);
 case "order.finish":Auth.role(u,"CAREGIVER");x=n(m,"orderId");o=orderScope(u,x);if(!o.get("status").equals("SERVING"))throw new Rule("订单不在服务中");d=db.one("SELECT * FROM v_dispatch_context WHERE order_id=? AND status='ACCEPTED'",x);db.update("UPDATE attendance SET check_out=NOW(6) WHERE dispatch_id=?",d.get("id"));db.call("verify_hours",d.get("id"));db.insert("INSERT INTO service_record(dispatch_id,notes) VALUES(?,?)",d.get("id"),s(m,"notes"));db.update("UPDATE dispatch SET status='FINISHED' WHERE id=?",d.get("id"));return db.update("UPDATE service_order SET status='CONFIRM' WHERE id=?",x);
 case "order.confirm":Auth.role(u,"FAMILY");x=n(m,"orderId");o=orderScope(u,x);if(!o.get("status").equals("CONFIRM"))throw new Rule("订单非待确认");db.update("UPDATE service_record r JOIN v_dispatch_context d ON d.id=r.dispatch_id SET r.confirmed_by=?,r.confirmed_at=NOW(),r.confirmation=? WHERE d.order_id=? AND d.status='FINISHED'",u.id(),s(m,"confirmation"),x);return db.update("UPDATE service_order SET status='COMPLETED' WHERE id=?",x);
 case "order.cancel":Auth.role(u,"ADMIN","FAMILY");x=n(m,"orderId");o=orderScope(u,x);if(!Set.of("PENDING","ASSIGNED","ACCEPTED").contains(o.get("status")))throw new Rule("当前状态不能取消");var ds=db.rows("SELECT * FROM v_dispatch_context WHERE order_id=? AND active_order IS NOT NULL",x);for(var z:ds){db.update("UPDATE dispatch SET status='REJECTED',reason=? WHERE id=?",s(m,"reason"),z.get("id"));db.update("UPDATE shift SET used_count=used_count-1 WHERE id=?",z.get("shift_id"));}return db.update("UPDATE service_order SET status='CANCELLED' WHERE id=?",x);
 case "complaint.create":Auth.role(u,"FAMILY");x=n(m,"orderId");if(!orderScope(u,x).get("status").equals("COMPLETED"))throw new Rule("服务完成后才能评价");return db.insert("INSERT INTO complaint(order_id,account_id,rating,content) VALUES(?,?,?,?)",x,u.id(),n(m,"rating"),s(m,"content"));
 case "shift.create":Auth.role(u,"MANAGER","ADMIN");x=n(m,"caregiverId");workerScope(u,x);return db.insert("INSERT INTO shift(caregiver_id,starts_at,ends_at,capacity) VALUES(?,?,?,?)",x,s(m,"startsAt"),s(m,"endsAt"),n(m,"capacity"));
 case "shift.delete":Auth.role(u,"MANAGER");x=n(m,"shiftId");var sh=db.one("SELECT * FROM shift WHERE id=? FOR UPDATE",x);workerScope(u,id(sh,"caregiver_id"));if(id(sh,"used_count")!=0)throw new Rule("已被使用的班次不能删除");return db.update("DELETE FROM shift WHERE id=? AND starts_at>NOW()",x);
 case "hours.review":Auth.role(u,"MANAGER");x=n(m,"attendanceId");var a=db.one("SELECT a.*,d.caregiver_id FROM attendance a JOIN v_dispatch_context d ON d.id=a.dispatch_id WHERE a.id=? FOR UPDATE",x);workerScope(u,id(a,"caregiver_id"));if(!a.get("status").equals("REVIEW"))throw new Rule("非待复核工时");if(b(m,"approve")&&db.count("SELECT TIMESTAMPDIFF(MINUTE,check_in,check_out) FROM attendance WHERE id=?",x)<=0)throw new Rule("有效服务时长必须大于零");return db.update("UPDATE attendance SET status=?,effective_minutes=IF(?,TIMESTAMPDIFF(MINUTE,check_in,check_out),0),reviewer_id=?,review_reason=? WHERE id=?",b(m,"approve")?"VALID":"INVALID",b(m,"approve"),u.id(),s(m,"reason"),x);
 case "device.bind":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);long device=n(m,"deviceId");var dev=db.one("SELECT * FROM device WHERE id=? FOR UPDATE",device);scope.community(u,id(dev,"community_id"));var bindings=db.rows("SELECT * FROM device_binding WHERE device_id=? AND unbound_at IS NULL",device);for(var z:bindings)elderScope(u,id(z,"elder_id"));db.update("UPDATE device_binding SET unbound_at=NOW(6) WHERE device_id=? AND unbound_at IS NULL",device);return db.insert("INSERT INTO device_binding(device_id,elder_id,bound_at) VALUES(?,?,NOW(6))",device,x);
 case "vital.upload":Auth.role(u,"ADMIN");var samples=m.get("samples");if(!(samples instanceof List<?> list)||list.isEmpty()||list.size()>500)throw new Rule("samples 必须为包含 1 至 500 条的数组");for(Object v:list){if(!(v instanceof Map<?,?>))throw new Rule("每条采样必须是对象");@SuppressWarnings("unchecked") var z=(Map<String,Object>)v;var bind=db.one("SELECT * FROM device_binding WHERE id=?",n(z,"bindingId"));elderScope(u,id(bind,"elder_id"));db.insert("INSERT INTO vital(binding_id,metric_rule_id,sample_key,collected_at,metric_value,source) VALUES(?,?,?,?,?,?)",n(z,"bindingId"),n(z,"metricId"),s(z,"sampleKey"),s(z,"collectedAt"),s(z,"value"),"SIMULATOR");}return list.size();
 case "event.create":Auth.role(u,"ADMIN","FAMILY","CAREGIVER");x=n(m,"elderId");elderScope(u,x);long level=n(m,"level");if(level<1||level>3)throw new Rule("事件等级应为 1 至 3");String source=u.role().equals("FAMILY")?"FAMILY_CALL":"MANUAL";long eventId=db.insert("INSERT INTO emergency(elder_id,source,level,deadline,status) VALUES(?,?,?,DATE_ADD(NOW(),INTERVAL ? SECOND),'OPEN')",x,source,level,level==1?300:level==2?180:60);db.insert("INSERT INTO emergency_log(event_id,level,message) VALUES(?,?,?)",eventId,level,s(m,"description"));return eventId;
 case "event.respond":Auth.role(u,"ADMIN","CAREGIVER");x=n(m,"eventId");var event=db.one("SELECT * FROM emergency WHERE id=? FOR UPDATE",x);elderScope(u,id(event,"elder_id"));if(!Set.of("OPEN","UNCONFIRMED").contains(event.get("status")))throw new Rule("事件已响应或关闭");return db.update("UPDATE emergency SET status='RESPONDED',responded_by=?,responded_at=NOW() WHERE id=?",u.id(),x);
 case "event.close":Auth.role(u,"ADMIN","CAREGIVER");x=n(m,"eventId");event=db.one("SELECT * FROM emergency WHERE id=? FOR UPDATE",x);elderScope(u,id(event,"elder_id"));if(!event.get("status").equals("RESPONDED"))throw new Rule("事件尚未响应");if(u.role().equals("CAREGIVER")&&id(event,"responded_by")!=u.id())throw new Forbidden();return db.update("UPDATE emergency SET status='CLOSED',arrived_at=NOW(),result=? WHERE id=?",s(m,"result"),x);
 case "claim.submit":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);try{db.call("submit_claim",x,n(m,"policyId"),s(m,"period"),new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(m.get("orderIds")));}catch(com.fasterxml.jackson.core.JsonProcessingException ex){throw new Rule("订单列表无效");}return "申报成功";
 case "claim.review":Auth.role(u,"STREET","REGULATOR");x=n(m,"claimId");var cl=db.one("SELECT * FROM claim WHERE id=? FOR UPDATE",x);scope.claim(u,x);String required=u.role().equals("STREET")?"SUBMITTED":"STREET_APPROVED";if(!cl.get("status").equals(required))throw new Rule("审核阶段不匹配");boolean approve=b(m,"approve");db.insert("INSERT INTO claim_review(claim_id,reviewer_id,stage,decision,reason) VALUES(?,?,?,?,?)",x,u.id(),u.role(),approve?"APPROVE":"REJECT",s(m,"reason"));return db.update("UPDATE claim SET status=? WHERE id=?",approve?(u.role().equals("STREET")?"STREET_APPROVED":"APPROVED"):"REJECTED",x);
 case "claim.pay":Auth.role(u,"REGULATOR");x=n(m,"claimId");cl=db.one("SELECT * FROM claim WHERE id=? FOR UPDATE",x);scope.claim(u,x);if(!cl.get("status").equals("APPROVED"))throw new Rule("申报尚未审批完成");db.insert("INSERT INTO payment(claim_id,reference_no,amount) VALUES(?,?,?)",x,s(m,"reference"),cl.get("amount"));return db.update("UPDATE claim SET status='PAID' WHERE id=?",x);
 case "inspection.create":Auth.role(u,"REGULATOR");x=n(m,"caregiverId");workerScope(u,x);return db.insert("INSERT INTO inspection(caregiver_id,inspector_id,method,score,issue,rectification) VALUES(?,?,?,?,?,?)",x,u.id(),s(m,"method"),n(m,"score"),s(m,"issue"),s(m,"rectification"));
 case "inspection.order":Auth.role(u,"REGULATOR");x=n(m,"orderId");orderScope(u,x);return db.insert("INSERT INTO inspection(order_id,inspector_id,method,score,issue,rectification) VALUES(?,?,?,?,?,?)",x,u.id(),s(m,"method"),n(m,"score"),s(m,"issue"),s(m,"rectification"));
 case "inspection.close":Auth.role(u,"REGULATOR");x=n(m,"inspectionId");var ins=db.one("SELECT i.*,a.community_id FROM inspection i JOIN account a ON a.id=i.inspector_id WHERE i.id=? FOR UPDATE",x);if(id(ins,"community_id")!=u.community())throw new Forbidden();return db.update("UPDATE inspection SET status='CLOSED',result=? WHERE id=?",s(m,"result"),x);
 case "maintenance.run":Auth.role(u,"ADMIN");db.call("expire_plans");db.call("escalate_events");return "到期及超时检查完成";
 default:throw new Rule("未知业务操作");
 }
 }
}
